topk(
  ${heap_prof_sample_limit},
  sum_over_time(ghc_eventlog_HeapProfSample_bytes{exported_job="${service_name}",exported_instance="${service_instance_id}",heapProfBreakdown="${heap_prof_breakdown}"}[${__range}] @ ${__to:date:seconds})
